# Moonruster component layer, Python side (module `_mr`; docs/PLUGINS.md).
# Copied from kaliru's src/plugins/prelude.py (@ b0e1435) and adapted to
# Moonraker.
#
# The mirror modules (generated by tools/gen_mirror.py) define Moonraker's
# classes as Python classes whose methods call into Moonruster through the
# native module `_moonruster`. This module supplies their building blocks and
# the import machinery:
#  - Object / Meta: the root of every mirrored class. Meta tells Moonruster
#    when a mirrored method is replaced on a class or overridden by a
#    subclass, and Object.__setattr__ when it is replaced on an instance, so
#    Moonruster's own calls of that method go to the Python replacement
#  - Attr: an instance attribute that lives in Moonruster (data descriptor).
#    An object a component built without a Moonruster object behind it is
#    plain Python: its attributes live in __dict__
#  - module_getattr: module names the mirror does not define at import
#    (values that need a third-party package) are computed on first access
#    by Moonraker's own statement (`_mr_lazy`), else asked from Moonruster
#  - logging: Python's root logger writes to Moonruster's log
#  - MirrorFinder: `moonraker.*` imports come from the mirror modules, which
#    carry the real file paths of the Moonraker tree as __file__; modules the
#    mirror does not have (third-party components) are files under that tree
import abc
import importlib
import importlib.machinery
import logging
import os
import sys

import _moonruster as _n

call = _n.call
fcall = _n.fcall
new = _n.new


# the mirror modules (install): a class defined in one is mirrored, any
# other subclass of a mirrored class is a component's
_mirror_modules = {}


class Meta(type):
    def __init__(cls, name, bases, ns):
        super().__init__(name, bases, ns)
        if cls.__module__ not in _mirror_modules and not ns.get("__mr_mirror__", False):
            # a component's subclass of a mirrored class: its methods override
            for key in ns:
                _n.patched_class(cls, key)

    def __setattr__(cls, name, value):
        super().__setattr__(name, value)
        _n.patched_class(cls, name)


class AbcMeta(Meta, abc.ABCMeta):
    """the metaclass of mirrored classes that are ABCs in Moonraker
    (common.RenderableTemplate, metaclass=ABCMeta)"""


class Object(metaclass=Meta):
    __mr_mirror__ = True
    __slots__ = ("_mr_h", "__dict__", "__weakref__")

    def __setattr__(self, name, value):
        object.__setattr__(self, name, value)
        if getattr(self, "_mr_h", None) is not None:
            _n.patched_instance(self, name)


class Attr:
    __slots__ = ("id", "name")

    def __init__(self, id, name):
        self.id = id
        self.name = name

    def __get__(self, obj, cls=None):
        if obj is None:
            # an instance attribute: Moonraker's class has no such class
            # attribute either (hasattr(cls, name) is False)
            raise AttributeError("type object %r has no attribute %r" % (cls.__name__, self.name))
        if getattr(obj, "_mr_h", None) is None:
            try:
                return obj.__dict__[self.name]
            except KeyError:
                raise AttributeError(
                    "%r object has no attribute %r" % (type(obj).__name__, self.name)
                ) from None
        return _n.get(obj, self.id)

    def __set__(self, obj, value):
        if getattr(obj, "_mr_h", None) is None:
            obj.__dict__[self.name] = value
        else:
            _n.set(obj, self.id, value)

    def __delete__(self, obj):
        if getattr(obj, "_mr_h", None) is None:
            del obj.__dict__[self.name]
        else:
            _n.delete(obj, self.id)


def attrs(cls, ids):
    """a mirrored class's instance attributes (generated at the module's end,
    so its methods keep Moonraker's line numbers); type.__setattr__: Meta's
    would report a patch"""
    for name, id in ids.items():
        type.__setattr__(cls, name, Attr(id, name))


class LazyAttr:
    """A class attribute whose value needs a third-party package
    (DbusManager.Variant = dbus_fast.Variant): Moonraker's own statement runs
    on first access, in the module's globals; the value then replaces this"""

    __slots__ = ("name", "code")

    def __init__(self, name, code):
        self.name = name
        self.code = code

    def __get__(self, obj, cls=None):
        if cls is None:
            cls = type(obj)
        g = dict(sys.modules[cls.__module__].__dict__)
        exec(self.code, g)
        value = g[self.name]
        type.__setattr__(cls, self.name, value)
        return value


def module_getattr(modname, lazy):
    def __getattr__(name):
        if name in lazy:
            g = sys.modules[modname].__dict__
            try:
                exec(lazy[name], g)
            except ImportError as e:
                # Moonraker's module has no such name when the package is
                # missing (hasattr() must say False, not raise)
                raise AttributeError(f"module {modname!r} has no attribute {name!r}") from e
            return g[name]
        return _n.module_value(modname, name)
    return __getattr__


class _HookLoader:
    """A module's own loader, with code to run after the module executed"""

    def __init__(self, loader, hooks):
        self.loader = loader
        self.hooks = hooks

    def create_module(self, spec):
        return self.loader.create_module(spec)

    def exec_module(self, module):
        # the module sees its own loader, as without the hook
        module.__spec__.loader = self.loader
        module.__loader__ = self.loader
        self.loader.exec_module(module)
        for hook in self.hooks:
            hook()

    def __getattr__(self, name):
        return getattr(self.loader, name)


class PostImportHooks:
    """Code to run once a module is first imported (sys.meta_path, ahead of
    the finders that find it)"""

    def __init__(self):
        self.hooks = {}

    def add(self, module, hook):
        self.hooks.setdefault(module, []).append(hook)

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in self.hooks:
            return None
        hooks = self.hooks.pop(fullname)
        for finder in sys.meta_path[sys.meta_path.index(self) + 1:]:
            find = getattr(finder, "find_spec", None)
            spec = find(fullname, path, target) if find is not None else None
            if spec is not None:
                if spec.loader is not None:
                    spec.loader = _HookLoader(spec.loader, hooks)
                return spec
        return None


_post_import = PostImportHooks()


_dbus_bus = None


async def dbus_interfaces(bus_name, bus_path, interface_names):
    """DbusManager.get_interfaces: dbus_fast proxies need a dbus_fast bus,
    Moonruster's own (Rust) connection is not one: the components get one of
    their own, connected on first use"""
    global _dbus_bus
    from dbus_fast.aio import MessageBus
    from dbus_fast.constants import BusType
    if _dbus_bus is None or not _dbus_bus.connected:
        _dbus_bus = await MessageBus(bus_type=BusType.SYSTEM).connect()
    introspection = await _dbus_bus.introspect(bus_name, bus_path)
    proxy_obj = _dbus_bus.get_proxy_object(bus_name, bus_path, introspection)
    return [proxy_obj.get_interface(n) for n in interface_names]


def _sqlite3_types():
    """SqliteProvider.__init__'s sqlite3 converters and adapters: Moonraker
    registers them at start, here once sqlite3 is imported"""
    import sqlite3
    from moonraker.utils import json_wrapper as jsonw

    def decode_record(bvalue):
        # Moonraker's database module imports sqlite3, so it may still be
        # importing here: its decode_record replaces this on first use
        from moonraker.components.database import decode_record
        sqlite3.register_converter("record", decode_record)
        return decode_record(bvalue)
    sqlite3.register_converter("record", decode_record)
    sqlite3.register_converter("pyjson", jsonw.loads)
    sqlite3.register_converter("pybool", lambda x: bool(x))
    sqlite3.register_adapter(list, jsonw.dumps)
    sqlite3.register_adapter(dict, jsonw.dumps)


def run_startup(modnames):
    """Moonraker's import-time side effects that need a third-party package
    (`_mr_startup`: http_client's AsyncHTTPClient.configure). Each runs once
    a module it imports is imported: before anything can use that package,
    without loading the package for components that never do"""
    if _post_import not in sys.meta_path:
        sys.meta_path.insert(0, _post_import)
    if "sqlite3" in sys.modules:
        _sqlite3_types()
    else:
        _post_import.add("sqlite3", _sqlite3_types)
    for name in modnames:
        mod = importlib.import_module(name)
        for triggers, code in mod.__dict__.get("_mr_startup", ()):
            done = []

            def run(code=code, g=mod.__dict__, done=done):
                if not done:
                    done.append(True)
                    exec(code, g)
            if not triggers or any(t in sys.modules for t in triggers):
                run()
            else:
                for t in triggers:
                    _post_import.add(t, run)


# The finder and loader are plain classes: the import system calls
# find_spec / create_module / exec_module by name, and importlib.abc would cost
# about 4 MB (it imports importlib.resources, typing, ...; measured on 3.12)
class MirrorLoader:
    def __init__(self, path):
        self.path = path

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        name = module.__spec__.name
        module.__file__ = self.path
        code = compile(_n.source(name), self.path, "exec")
        exec(code, module.__dict__)


class MirrorFinder:
    def __init__(self, moonraker_dir, modules):
        self.moonraker_dir = moonraker_dir  # the tree's `moonraker` package dir
        self.modules = modules  # mirrored name -> is a package

    def find_spec(self, fullname, path=None, target=None):
        if fullname not in self.modules:
            return None  # a file in the Moonraker tree (normal path finder)
        is_pkg = self.modules[fullname]
        rel = os.path.join(self.moonraker_dir, *fullname.split(".")[1:])
        file = os.path.join(rel, "__init__.py") if is_pkg else rel + ".py"
        spec = importlib.machinery.ModuleSpec(fullname, MirrorLoader(file), is_package=is_pkg, origin=file)
        spec.has_location = True
        if is_pkg:
            # third-party components in moonraker/components are found here
            spec.submodule_search_locations = [rel]
        return spec


_unofficial = None


class ConfigView:
    """ConfigHelper.config: the parser Moonraker's getters read through.
    Values and errors are configparser's own (get / getint / getfloat /
    getboolean); `raw(section, option)` gives (0, value), (1, None) for a
    missing section, (2, None) for a missing option"""
    __slots__ = ("_raw", "_sections", "_has")

    def __init__(self, raw, sections, has):
        self._raw, self._sections, self._has = raw, sections, has

    def get(self, section, option, **kwargs):
        import configparser
        status, value = self._raw(section, option)
        if status == 1:
            raise configparser.NoSectionError(section)
        if status == 2:
            raise configparser.NoOptionError(option, section)
        return value

    def getint(self, section, option, **kwargs):
        return int(self.get(section, option))

    def getfloat(self, section, option, **kwargs):
        return float(self.get(section, option))

    def getboolean(self, section, option, **kwargs):
        import configparser
        value = self.get(section, option)
        states = configparser.RawConfigParser.BOOLEAN_STATES
        if value.lower() not in states:
            raise ValueError('Not a boolean: %s' % value)
        return states[value.lower()]

    def sections(self):
        return self._sections()

    def has_section(self, section):
        return section in self._sections()

    def has_option(self, section, option):
        return self._raw(section, option)[0] == 0

    def __contains__(self, section):
        return self._has(section)


class TableView:
    """Server.components / failed_components as Moonraker's own code uses
    them (`name in`, `[name]`, `[name] = component`, `.append(name)`):
    views of Moonruster's tables, through the server's handlers"""
    __slots__ = ("_has", "_get", "_set", "_names")

    def __init__(self, has, get, set, names):
        self._has, self._get, self._set, self._names = has, get, set, names

    def __contains__(self, key):
        return self._has(key)

    def __getitem__(self, key):
        if not self._has(key):
            raise KeyError(key)
        return self._get(key)

    def __setitem__(self, key, value):
        self._set(key, value)

    def get(self, key, default=None):
        return self._get(key) if self._has(key) else default

    def append(self, key):
        self._set(key, None)

    def __iter__(self):
        return iter(self._names())

    def __len__(self):
        return len(self._names())

    def keys(self):
        return list(self._names())

    def __repr__(self):
        return repr(list(self._names()))


async def deliver(aw, done):
    """A task Rust awaits (futures.rs await_py): `await aw` as Moonraker's
    caller does, so a value that is not awaitable raises Python's own
    TypeError ("object dict can't be used in 'await' expression"). The
    outcome reaches Rust in the step that finishes `aw`: Moonraker's caller
    goes on in that step, before the tasks `aw` scheduled (a done callback
    would come one loop iteration later, after them)"""
    try:
        result = await aw
    except BaseException as e:
        done(False, e)
        if not isinstance(e, Exception):
            raise
    else:
        done(True, result)


class LogHandler(logging.Handler):
    """Moonraker's file handler, through Moonruster's log writer: the
    record's own file, function and line, and the message with the
    traceback appended (logging.Formatter('%(message)s') does that)"""

    def emit(self, record):
        try:
            _n.log(record.levelno, record.filename, record.funcName, record.lineno, self.format(record))
        except Exception:
            self.handleError(record)


def software_info():
    """Moonraker's get_software_info(), which it runs at startup (its
    unofficial_components decide pip recovery)"""
    global _unofficial
    from moonraker.utils import get_software_info
    _unofficial = get_software_info().get("unofficial_components", [])


def install(moonraker_dir, modules, log_level):
    _mirror_modules.update(modules)
    sys.meta_path.insert(0, MirrorFinder(moonraker_dir, dict(modules)))
    # as Moonraker's startup: get_software_info() runs before logging is set
    # up (an error there goes to stderr through the handler logging's
    # module-level functions add), then loghelper removes that handler
    software_info()
    root = logging.getLogger()
    while root.hasHandlers():
        root.removeHandler(root.handlers[0])
    handler = LogHandler()
    handler.setFormatter(logging.Formatter("%(message)s"))
    root.addHandler(handler)
    root.setLevel(log_level)
